function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 300) return 'nums needs 1 to 300 rows.';
  for (const row of nums) {
    if (!Array.isArray(row) || row.length !== nums.length) return 'nums must be square: every row has n values.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 4000000)) return 'Each value is an integer from 1 to 4 * 10^6.';
  }
  return null;
}

