  const limit = Math.max(...onDiagonal);
  // Sieve of Eratosthenes up to the largest diagonal value.
  const composite = new Uint8Array(limit + 1);
  composite[0] = 1;
  composite[1] = 1;
  for (let p = 2; p * p <= limit; p++) if (!composite[p]) for (let q = p * p; q <= limit; q += p) composite[q] = 1;
  let answer = 0;
  for (const v of onDiagonal) if (!composite[v] && v > answer) answer = v;
  return answer;
}

