    for (let i = 0; i < n; i++) {
      for (const j of [i, n - 1 - i]) {
        // Mode 1: only even values on the diagonals, so the answer is at most 2.
        if (mode === 1) grid[i][j] = rand() < 0.01 ? 2 : 2 * (1 + Math.floor(rand() * 2000000));
        // Mode 2: squares of primes and other near-misses, with one big prime hidden somewhere.
        if (mode === 2) grid[i][j] = [3996001, 1, 4000000, 1997 * 1999, 9][Math.floor(rand() * 5)];
      }
    }
    if (mode === 2) {
      const i = Math.floor(rand() * n);
      grid[i][rand() < 0.5 ? i : n - 1 - i] = bigPrimes[Math.floor(rand() * 4)];
    }
    return [grid];
  }
  const n = 1 + Math.floor(rand() * 5);
  const span = rand() < 0.5 ? 30 : 200;
  const grid = Array.from({ length: n }, () => Array.from({ length: n }, () => {
